157→  });
158→
159→  describe('timer: auto-transition from SHOW_NOTE to SHOW_ANSWER after 5 seconds', () => {
160→    beforeEach(() => {
161→      vi.useFakeTimers();
162→    });
163→
164→    afterEach(() => {
165→      vi.useRealTimers();
