167→
168→    it('should automatically transition to SHOW_ANSWER after 5 seconds in SHOW_NOTE', () => {
169→      service.start();
170→      expect(service.state()).toBe(GameState.SHOW_NOTE);
171→
172→      vi.advanceTimersByTime(5000);
173→
174→      expect(service.state()).toBe(GameState.SHOW_ANSWER);
