180→      vi.advanceTimersByTime(4999);
181→
182→      expect(service.state()).toBe(GameState.SHOW_NOTE);
183→    });
184→
185→    it('should keep the same current note after auto-transition to SHOW_ANSWER', () => {
186→      service.start();
187→      const note = service.currentNote();
188→
189→      vi.advanceTimersByTime(5000);
190→
191→      expect(service.currentNote()).toBe(note);
192→    });
