194→
195→  describe('timer: auto-transition from SHOW_ANSWER to next SHOW_NOTE after 3 seconds', () => {
196→    beforeEach(() => {
197→      vi.useFakeTimers();
198→    });
199→
200→    afterEach(() => {
201→      vi.useRealTimers();
202→    });
203→
204→    it('should automatically transition to SHOW_NOTE after 3 seconds in SHOW_ANSWER', () => {
205→      service.start();
206→      vi.advanceTimersByTime(5000); // auto-transition to SHOW_ANSWER
207→      expect(service.state()).toBe(GameState.SHOW_ANSWER);
208→
209→      vi.advanceTimersByTime(3000);
210→
211→      expect(service.state()).toBe(GameState.SHOW_NOTE);
212→    });
213→
214→    it('should not transition before 3 seconds have elapsed', () => {
215→      service.start();
216→      vi.advanceTimersByTime(5000);
217→
218→      vi.advanceTimersByTime(2999);
219→
220→      expect(service.state()).toBe(GameState.SHOW_ANSWER);
221→    });
222→
223→    it('should draw a new note after auto-transition from SHOW_ANSWER', () => {
224→      const progression = TestBed.inject(ProgressionService);
225→      vi.spyOn(progression, 'drawNote');
226→
