228→      expect(progression.drawNote).toHaveBeenCalledTimes(1);
229→
230→      vi.advanceTimersByTime(5000); // to SHOW_ANSWER
231→      vi.advanceTimersByTime(3000); // to SHOW_NOTE (next)
