233→      expect(progression.drawNote).toHaveBeenCalledTimes(2);
234→    });
235→  });
236→
237→  describe('timer: continuous game loop', () => {
238→    beforeEach(() => {
239→      vi.useFakeTimers();
240→    });
241→
242→    afterEach(() => {
243→      vi.useRealTimers();
244→    });
245→
246→    it('should automatically cycle through multiple rounds', () => {
247→      service.start();
248→
249→      for (let i = 0; i < 3; i++) {
250→        expect(service.state()).toBe(GameState.SHOW_NOTE);
251→        vi.advanceTimersByTime(5000);
252→        expect(service.state()).toBe(GameState.SHOW_ANSWER);
253→        vi.advanceTimersByTime(3000);
254→      }
255→
256→      expect(service.state()).toBe(GameState.SHOW_NOTE);
257→    });
258→  });
