260→  describe('timer: cancellation', () => {
261→    beforeEach(() => {
262→      vi.useFakeTimers();
263→    });
264→
265→    afterEach(() => {
266→      vi.useRealTimers();
267→    });
268→
269→    it('should cancel the timer when stop is called during SHOW_NOTE', () => {
270→      service.start();
271→      service.stop();
272→
273→      vi.advanceTimersByTime(5000);
274→
275→      expect(service.state()).toBe(GameState.IDLE);
276→    });
277→
278→    it('should cancel the timer when stop is called during SHOW_ANSWER', () => {
279→      service.start();
280→      vi.advanceTimersByTime(5000); // to SHOW_ANSWER
