288→    it('should cancel the SHOW_NOTE timer when showAnswer is called manually before timeout', () => {
289→      service.start();
290→      service.showAnswer(); // manual transition before 5s
291→
292→      vi.advanceTimersByTime(5000);
293→
294→      // should not have double-transitioned; should still be in SHOW_ANSWER
295→      // (or moved to next SHOW_NOTE via the answer timer, but not broken)
296→      expect(service.state()).not.toBe(GameState.IDLE);
297→    });
298→
299→    it('should cancel the SHOW_ANSWER timer when nextNote is called manually before timeout', () => {
300→      service.start();
301→      vi.advanceTimersByTime(5000); // to SHOW_ANSWER
302→      service.nextNote(); // manual transition before 3s
303→
304→      vi.advanceTimersByTime(3000);
305→
306→      // should not have called nextNote again; should be in SHOW_NOTE with its own timer
307→      expect(service.state()).toBe(GameState.SHOW_NOTE);
