320→    it('should clear pending timer when ngOnDestroy is called mid-game', () => {
321→      service.start();
322→      expect(service.state()).toBe(GameState.SHOW_NOTE);
323→
324→      service.ngOnDestroy();
325→
326→      vi.advanceTimersByTime(5000);
327→
328→      // Timer should have been cleared — state should NOT have advanced to SHOW_ANSWER
329→      expect(service.state()).toBe(GameState.SHOW_NOTE);
330→    });
331→  });
332→
333→  describe('ProgressionService integration', () => {
334→    it('should populate currentNote with the exact note returned by ProgressionService.drawNote', () => {
335→      const progression = TestBed.inject(ProgressionService);
336→      const fakeNote: FretNote = { string: 1, fret: 0, note: 'E', x: 50, y: 10 };
337→      vi.spyOn(progression, 'drawNote').mockReturnValue(fakeNote);
338→
339→      service.start();
340→
341→      expect(service.currentNote()).toBe(fakeNote);
342→    });
343→
344→    it('should populate currentNote with the note from drawNote on nextNote transition', () => {
345→      const progression = TestBed.inject(ProgressionService);
346→      const firstNote: FretNote = { string: 6, fret: 0, note: 'E', x: 50, y: 90 };
347→      const secondNote: FretNote = { string: 5, fret: 0, note: 'A', x: 50, y: 75 };
348→      vi.spyOn(progression, 'drawNote')
349→        .mockReturnValueOnce(firstNote)
350→        .mockReturnValueOnce(secondNote);
351→
352→      service.start();
353→      expect(service.currentNote()).toBe(firstNote);
354→
355→      service.showAnswer();
356→      service.nextNote();
357→      expect(service.currentNote()).toBe(secondNote);
358→    });
359→
360→    it('should provide notes that belong to the current progression pool', () => {
361→      const progression = TestBed.inject(ProgressionService);
362→
363→      service.start();
364→      const note = service.currentNote()!;
365→      const pool = progression.getCurrentPool();
366→
367→      expect(pool.some(p => p.string === note.string && p.fret === note.fret)).toBe(true);
368→    });
369→
370→    it('should trigger pool expansion after all open string notes have been drawn', () => {
371→      const progression = TestBed.inject(ProgressionService);
372→      const openStrings = [...progression.getCurrentPool()];
373→      expect(openStrings.length).toBe(6);
374→
375→      // Control Math.random to return each open string note in sequence
376→      let callIndex = 0;
377→      vi.spyOn(Math, 'random').mockImplementation(() => {
378→        // Return values that map to indices 0..5 sequentially for a pool of 6
379→        const index = callIndex % openStrings.length;
380→        callIndex++;
381→        return index / openStrings.length;
382→      });
383→
384→      // Run through 6 game cycles (start + 5 nextNote calls)
385→      service.start(); // draws note 0
386→      for (let i = 1; i < openStrings.length; i++) {
387→        service.showAnswer();
388→        service.nextNote(); // draws note i
389→      }
390→
391→      // After all 6 open string notes shown, pool should have expanded
392→      expect(progression.getCurrentFret()).toBeGreaterThan(0);
393→
394→      vi.restoreAllMocks();
395→    });
396→
397→    it('should continue the game loop after pool expansion with notes from the expanded pool', () => {
398→      const progression = TestBed.inject(ProgressionService);
399→      const openStrings = [...progression.getCurrentPool()];
400→
401→      // Force all open strings to be marked as shown to trigger expansion
402→      for (const note of openStrings) {
403→        progression.markNoteAsShown(note);
404→      }
405→
406→      // Pool should now be expanded
407→      expect(progression.getCurrentFret()).toBeGreaterThan(0);
408→      const expandedPool = progression.getCurrentPool();
409→
410→      // Start game — should draw from expanded pool
411→      service.start();
412→      const note = service.currentNote()!;
413→      expect(expandedPool.some(p => p.string === note.string && p.fret === note.fret)).toBe(true);
414→    });
415→
416→    it('should reset progression pool when the game is stopped and restarted', () => {
417→      const progression = TestBed.inject(ProgressionService);
418→
419→      // Expand pool manually
420→      const openStrings = [...progression.getCurrentPool()];
421→      for (const note of openStrings) {
422→        progression.markNoteAsShown(note);
423→      }
424→      expect(progression.getCurrentFret()).toBeGreaterThan(0);
425→
426→      // Start and stop game
427→      service.start();
428→      service.stop();
429→
430→      // Pool should be back to open strings
431→      expect(progression.getCurrentFret()).toBe(0);
432→      expect(progression.getCurrentPool().length).toBe(6);
433→
434→      // Restarting should draw from initial pool
435→      service.start();
436→      const note = service.currentNote()!;
437→      expect(note.fret).toBe(0);
438→    });
439→
440→    it('should mark drawn notes as shown in the progression service', () => {
441→      const progression = TestBed.inject(ProgressionService);
442→
443→      service.start();
444→      const firstNote = service.currentNote()!;
445→
446→      expect(progression.hasBeenShown(firstNote)).toBe(true);
447→    });
448→  });
449→
450→  describe('full cycle', () => {
451→    it('should complete a full game cycle: IDLE -> SHOW_NOTE -> SHOW_ANSWER -> SHOW_NOTE (next)', () => {
452→      const progression = TestBed.inject(ProgressionService);
453→      vi.spyOn(progression, 'drawNote');
454→
455→      expect(service.state()).toBe(GameState.IDLE);
456→
457→      service.start();
458→      expect(service.state()).toBe(GameState.SHOW_NOTE);
459→      const firstNote = service.currentNote();
460→      expect(firstNote).not.toBeNull();
461→      expect(progression.drawNote).toHaveBeenCalledTimes(1);
462→
463→      service.showAnswer();
464→      expect(service.state()).toBe(GameState.SHOW_ANSWER);
465→      expect(service.currentNote()).toBe(firstNote);
466→
467→      service.nextNote();
468→      expect(service.state()).toBe(GameState.SHOW_NOTE);
469→      expect(service.currentNote()).not.toBeNull();
470→      expect(progression.drawNote).toHaveBeenCalledTimes(2);
471→    });
472→
473→    it('should be able to run multiple cycles', () => {
474→      service.start();
475→
476→      for (let i = 0; i < 5; i++) {
477→        expect(service.state()).toBe(GameState.SHOW_NOTE);
478→        expect(service.currentNote()).not.toBeNull();
479→
480→        service.showAnswer();
481→        expect(service.state()).toBe(GameState.SHOW_ANSWER);
482→
483→        service.nextNote();
484→      }
485→
486→      expect(service.state()).toBe(GameState.SHOW_NOTE);
487→    });
488→  });
489→});
