import { ChangeDetectionStrategy, Component, computed, inject } from '@angular/core';
import { GameState, GameStateService } from '../game-state.service';
import { ProgressionService } from '../progression.service';
import { NoteDataService } from '../note-data.service';
import { FretboardDisplayComponent } from '../fretboard-display/fretboard-display';

@Component({
  selector: 'app-fretboard-flash-page',
  templateUrl: './fretboard-flash-page.html',
  styleUrl: './fretboard-flash-page.scss',
  changeDetection: ChangeDetectionStrategy.OnPush,
  imports: [FretboardDisplayComponent],
  providers: [GameStateService, ProgressionService, NoteDataService],
})
export class FretboardFlashPageComponent {
  private readonly gameState = inject(GameStateService);

  readonly state = this.gameState.state;
  readonly currentNote = this.gameState.currentNote;
  readonly isIdle = computed(() => this.state() === GameState.IDLE);
  readonly isShowAnswer = computed(() => this.state() === GameState.SHOW_ANSWER);
  readonly fretboardNote = computed(() => this.isShowAnswer() ? this.currentNote() : null);

  start(): void {
    this.gameState.start();
  }

  stop(): void {
    this.gameState.stop();
  }
}
<div class="fretboard-flash-page" data-testid="fretboard-flash-page">
  @if (!isIdle()) {
    <div class="note-display" data-testid="note-display">
      {{ currentNote()?.note }}
    </div>
  }

  <app-fretboard-display [note]="fretboardNote()" />

  <div class="game-controls" data-testid="game-controls">
    @if (isIdle()) {
      <button
        data-testid="start-button"
        class="game-button game-button--start"
        (click)="start()"
        i18n="Start game button@@fretboardFlash.startButton"
      >
        Start
      </button>
    } @else {
      <button
        data-testid="stop-button"
        class="game-button game-button--stop"
        (click)="stop()"
        i18n="Stop game button@@fretboardFlash.stopButton"
      >
        Stop
      </button>
    }
  </div>
</div>
:host {
  display: block;
}

.fretboard-flash-page {
  display: flex;
  flex-direction: column;
  align-items: center;
  padding: 2rem 1rem;
  max-width: 900px;
  margin: 0 auto;
}

.note-display {
  font-size: 6rem;
  font-weight: 800;
  color: var(--gt-primary);
  text-align: center;
  margin-bottom: 1.5rem;
  line-height: 1;
}

.game-controls {
  margin-top: 1.5rem;
}

.game-button {
  padding: 0.75rem 2rem;
  border: none;
  border-radius: 0.8rem;
  font-size: 1.1rem;
  font-weight: 600;
  cursor: pointer;
  transition: background-color 0.3s ease;

  &--start {
    background-color: #fd8d32;
    color: #fff;
  }

  &--stop {
    background-color: #979797;
    color: #fff;
  }
}
